REVOKE GRANT OPTION FOR SELECT ON `t` FROM u1;
revoke grant option for ALL ON `t` FROM u1;
REVOKE 'ydb.access.grant' ON `t` FROM u1;
DROP USER IF EXISTS u1;
drop group g1;
DROP GROUP IF EXISTS g2, g3;
DROP RESOURCE POOL default;
DROP RESOURCE POOL IF EXISTS default;
DROP RESOURCE POOL `default`;
DROP RESOURCE POOL Default;
DROP RESOURCE POOL CLASSIFIER default;
DROP BACKUP COLLECTION `bc`;
DROP BACKUP COLLECTION IF EXISTS bc2;
ANALYZE `t`, `u`;
analyze t (a, b);
